 SET search_path TO ''
AS $function$ select "better_supabase"."workflow_node_kinds_list"() $function$;

ALTER TABLE "better_supabase"."inbox_drafts" ADD CONSTRAINT "inbox_drafts_author_id_fkey" FOREIGN KEY (author_id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "better_supabase"."inbox_drafts" ADD CONSTRAINT "inbox_drafts_conversation_id_fkey" FOREIGN KEY (conversation_id) REFERENCES better_supabase.inbox_conversations(id) ON DELETE CASCADE;

ALTER TABLE "better_supabase"."knowledge_collection_grants" ADD CONSTRAINT "knowledge_collection_grants_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "better_supabase"."knowledge_collections" ADD CONSTRAINT "knowledge_collections_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE "better_supabase"."knowledge_collection_grants" ADD CONSTRAINT "knowledge_collection_grants_collection_id_fkey" FOREIGN KEY (collection_id) REFERENCES better_supabase.knowledge_collections(id) ON DELETE CASCADE;

ALTER TABLE "better_supabase"."knowledge_documents" ADD CONSTRAINT "knowledge_documents_collection_id_fkey" FOREIGN KEY (collection_id) REFERENCES better_supabase.knowledge_collections(id) ON DELETE SET NULL;

ALTER TABLE "better_supabase"."knowledge_documents" ADD CONSTRAINT "knowledge_documents_system_check" CHECK (((organization_id IS NOT NULL) OR ((scope = 'organization'::text) AND (owner_id IS NULL))));

ALTER TABLE "better_supabase"."workflow_definitions" ADD CONSTRAINT "workflow_definitions_purpose_check" CHECK ((purpose = ANY (ARRAY['automation'::text, 'lifecycle'::text])));

CREATE INDEX inbox_drafts_author_idx ON better_supabase.inbox_drafts USING btree (author_id);

CREATE INDEX inbox_drafts_conversation_idx ON better_supabase.inbox_drafts USING btree (conversation_id);

CREATE UNIQUE INDEX inbox_drafts_open_key ON better_supabase.inbox_drafts USING btree (conversation_id, author_id) WHERE ((source = 'user'::text) AND (status = 'draft'::text));

CREATE UNIQUE INDEX knowledge_collection_grants_key ON better_supabase.knowledge_collection_grants USING btree (collection_id, user_id, team_id) NULLS NOT DISTINCT;

CREATE INDEX knowledge_collection_grants_user_idx ON better_supabase.knowledge_collection_grants USING btree (user_id) WHERE (user_id IS NOT NULL);

CREATE INDEX knowledge_collections_created_by_idx ON better_supabase.knowledge_collections USING btree (created_by);

CREATE UNIQUE INDEX knowledge_collections_name_key ON better_supabase.knowledge_collections USING btree (organization_id, name) NULLS NOT DISTINCT;

CREATE INDEX knowledge_documents_collection_idx ON better_supabase.knowledge_documents USING btree (collection_id) WHERE (collection_id IS NOT NULL);

CREATE INDEX memories_deleted_idx ON better_supabase.memories USING btree (deleted_at) WHERE (deleted_at IS NOT NULL);

CREATE INDEX memories_expires_idx ON better_supabase.memories USING btree (expires_at) WHERE (expires_at IS NOT NULL);

CREATE UNIQUE INDEX memories_path_idx ON better_supabase.memories USING btree (organization_id, owner_id, scope, agent_id, chat_id, project_id, subject_type, subject_id, path) NULLS NOT DISTINCT WHERE ((path IS NOT NULL) AND (superseded_by IS NULL) AND (deleted_at IS NULL));

CREATE INDEX memories_pending_embedding_idx ON better_supabase.memories USING btree (updated_at) WHERE ((embedding IS NULL) AND (superseded_by IS NULL) AND (deleted_at IS NULL));

CREATE INDEX memories_subject_idx ON better_supabase.memories USING btree (subject_type, subject_id) WHERE (subject_id IS NOT NULL);

CREATE INDEX workflow_definitions_default_idx ON better_supabase.workflow_definitions USING btree (tenant_id, purpose) WHERE is_default;

CREATE TRIGGER bsb_updated_at BEFORE UPDATE ON better_supabase.inbox_drafts FOR EACH ROW EXECUTE FUNCTION better_supabase.set_updated_at('updated_at');

CREATE POLICY "bsb_tenant_scope_delete" ON "better_supabase"."inbox_drafts" AS RESTRICTIVE FOR DELETE TO PUBLIC USING ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "bsb_tenant_scope_insert" ON "better_supabase"."inbox_drafts" AS RESTRICTIVE FOR INSERT TO PUBLIC WITH CHECK ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "bsb_tenant_scope_select" ON "better_supabase"."inbox_drafts" AS RESTRICTIVE FOR SELECT TO PUBLIC USING (((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR (((author_id = ( SELECT auth.uid() AS uid)) OR (source = 'ai'::text)) AND (tenant_id IN ( SELECT better_supabase.tenant_ids_with('inbox.reply'::text) AS tenant_ids_with)))));

CREATE POLICY "bsb_tenant_scope_update" ON "better_supabase"."inbox_drafts" AS RESTRICTIVE FOR UPDATE TO PUBLIC USING ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids))) WITH CHECK ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "inbox_drafts_read" ON "better_supabase"."inbox_drafts" FOR SELECT TO "authenticated" USING ((((author_id = ( SELECT auth.uid() AS uid)) OR (source = 'ai'::text)) AND (tenant_id IN ( SELECT better_supabase.tenant_ids_with('inbox.reply'::text) AS tenant_ids_with))));

CREATE POLICY "bsb_tenant_scope_delete" ON "better_supabase"."knowledge_collections" AS RESTRICTIVE FOR DELETE TO PUBLIC USING ((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "bsb_tenant_scope_insert" ON "better_supabase"."knowledge_collections" AS RESTRICTIVE FOR INSERT TO PUBLIC WITH CHECK ((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "bsb_tenant_scope_select" ON "better_supabase"."knowledge_collections" AS RESTRICTIVE FOR SELECT TO PUBLIC USING (((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR better_supabase.knowledge_collection_readable(id)));

CREATE POLICY "bsb_tenant_scope_update" ON "better_supabase"."knowledge_collections" AS RESTRICTIVE FOR UPDATE TO PUBLIC USING ((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids))) WITH CHECK ((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "knowledge_collections_read" ON "better_supabase"."knowledge_collections" FOR SELECT TO "authenticated" USING (better_supabase.knowledge_collection_readable(id));

CREATE POLICY "bsb_tenant_scope_select" ON "better_supabase"."knowledge_documents" AS RESTRICTIVE FOR SELECT TO PUBLIC USING (((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR (((organization_id IS NULL) OR (owner_id = ( SELECT auth.uid() AS uid)) OR ((scope = ANY (ARRAY['organization'::text, 'agent'::text])) AND (organization_id IN ( SELECT better_supabase.tenant_ids_with('ai.read'::text) AS tenant_ids_with))) OR (organization_id IN ( SELECT better_supabase.tenant_ids_with('ai.admin'::text) AS tenant_ids_with)) OR ((scope = 'chat'::text) AND ((scope_id IS NOT NULL) AND better_supabase.ai_chat_can_read(scope_id)))) AND ((collection_id IS NULL) OR better_supabase.knowledge_collection_readable(collection_id)))));

CREATE POLICY "knowledge_documents_read" ON "better_supabase"."knowledge_documents" FOR SELECT TO "authenticated" USING ((((organization_id IS NULL) OR (owner_id = ( SELECT auth.uid() AS uid)) OR ((scope = ANY (ARRAY['organization'::text, 'agent'::text])) AND (organization_id IN ( SELECT better_supabase.tenant_ids_with('ai.read'::text) AS tenant_ids_with))) OR (organization_id IN ( SELECT better_supabase.tenant_ids_with('ai.admin'::text) AS tenant_ids_with)) OR ((scope = 'chat'::text) AND ((scope_id IS NOT NULL) AND better_supabase.ai_chat_can_read(scope_id)))) AND ((collection_id IS NULL) OR better_supabase.knowledge_collection_readable(collection_id))));

CREATE POLICY "bsb_tenant_scope_select" ON "better_supabase"."memories" AS RESTRICTIVE FOR SELECT TO PUBLIC USING (((organization_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR (((owner_id = ( SELECT auth.uid() AS uid)) OR ((scope = ANY (ARRAY['organization'::text, 'record'::text])) AND (organization_id IN ( SELECT better_supabase.tenant_ids_with('ai.read'::text) AS tenant_ids_with)))) AND (deleted_at IS NULL))));

CREATE POLICY "memories_read" ON "better_supabase"."memories" FOR SELECT TO "authenticated" USING ((((owner_id = ( SELECT auth.uid() AS uid)) OR ((scope = ANY (ARRAY['organization'::text, 'record'::text])) AND (organization_id IN ( SELECT better_supabase.tenant_ids_with('ai.read'::text) AS tenant_ids_with)))) AND (deleted_at IS NULL)));

CREATE POLICY "workflow_node_kinds_read" ON "better_supabase"."workflow_node_kinds" FOR SELECT TO "authenticated" USING (true);

